    for i in range(n):
        if a[i] % 2 == 0:
            queue_even.append(i)
        else:
            queue_odd.append(i)

    def bfs(queue, target_parity):
        steps = 0
        visited = [False] * n

        while queue:
            new_queue = []

            for pos in queue:
                if not visited[pos]:
                    visited[pos] = True
                    if dist[pos] == -1:
                        dist[pos] = steps

                    # Calculate possible jumps
                    left_jump = pos - a[pos]
                    right_jump = pos + a[pos]

                    if 0 <= left_jump < n and a[left_jump] % 2 == target_parity:
                        if dist[left_jump] == -1:
