        matrix = [input().split() for _ in range(N)]

        # Initialize DP table
        dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

        # Fill the DP table
        for i in range(N):
            for j in range(N):
                if matrix[i][j] == 'a':
                    dp[i][j][0] = 1  # Count of 'a'
                else:
                    dp[i][j][0] = 0  # No 'a'

                dp[i][j][1] = 1  # Path length is always at least 1 (itself)

                if i > 0:
                    if dp[i-1][j][0] > dp[i][j][0] or (dp[i-1][j][0] == dp[i][j][0] and dp[i-1][j][1] + 1 < dp[i][j][1]):
