def next_good_number(n):
    # Convert n to its ternary (base-3) representation
    ternary_digits = []
    while n > 0:
        ternary_digits.append(n % 3)
        n //= 3

    # Process the ternary digits from least significant to most significant
    carry = 0
    for i in range(len(ternary_digits)):
        if ternary_digits[i] == 2:
            ternary_digits[i] = 0
            carry = 1
        elif carry == 1:
            if ternary_digits[i] == 1:
                ternary_digits[i] = 0
            else:
                ternary_digits[i] = 1
                carry = 0

    # If there was a carry left after processing all digits, add a new leading '1'
    if carry == 1:
        ternary_digits.append(1)

    # Calculate the smallest good number by converting back from ternary to decimal
    result = 0
    power_of_3 = 1
    for digit in ternary_digits:
        result += digit * power_of_3
        power_of_3 *= 3

    return result


