def find_min_k(n, f):
    def apply_function(k, x):
        # Apply the function f k times to x
        for _ in range(k):
            x = f[x - 1]
        return x

    k = 1
    while True:
        # Check if f^(k)(x) is idempotent for all x
        is_idempotent = True
        for x in range(1, n + 1):
            if apply_function(k, apply_function(k, x)) != apply_function(k, x):
                is_idempotent = False
                break
        if is_idempotent:
            return k
        k += 1

