def find_grid(s):
    # Create a dictionary to store positions of each character
    positions = {chr(ord("A") + i): [] for i in range(26)}
    positions[s[26]] = []

    # Initialize a 2x13 grid with empty strings
    grid = [["" for _ in range(13)] for _ in range(2)]

    # Fill the grid row-wise
    index = 0
    for i in range(2):
        for j in range(13):
            grid[i][j] = s[index]
            positions[s[index]].append((i, j))
            index += 1

    # Function to check if two positions are adjacent
    def are_adjacent(pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1 and (x1 != x2 or y1 != y2)

    # Check if we can form the path
    for i in range(1, 27):
        prev_positions = positions[s[i - 1]]
        curr_positions = positions[s[i]]

        found = False
        for px, py in prev_positions:
            for cx, cy in curr_positions:
                if are_adjacent((px, py), (cx, cy)):
                    found = True
                    break
            if found:
                break

        if not found:
            return "Impossible"

    # Convert grid to the required format
    return "\n".join(["".join(row) for row in grid])


