def count_good_subsequences(n, arr):
    # Initialize dp array
    dp = [0] * (1 << n)

    # Iterate over all possible subsequences
    for mask in range(1, 1 << n):
        # Count the number of set bits in the mask
        count_set_bits = bin(mask).count("1")

        # Check if the subsequence starts with count_set_bits - 1
        if count_set_bits == 1:
            idx = 0
            while (mask >> idx) & 1 == 0:
                idx += 1
            if arr[idx] == count_set_bits - 1:
                dp[mask] = 1
        else:
            # Find the starting index of the current subsequence
            idx = 0
            while (mask >> idx) & 1 == 0:
                idx += 1

            # If the first element is count_set_bits - 1
            if arr[idx] == count_set_bits - 1:
                # Try to split the subsequence into valid good arrays
                for j in range(idx + 1, n):
                    if (mask >> j) & 1 == 1:
                        prefix_mask = (1 << (j - idx)) - 1
                        if dp[prefix_mask << idx] > 0:
                            dp[mask] = (dp[mask] + dp[prefix_mask << idx]) % MOD

    # Sum up all good subsequences
    total_good_sequences = sum(dp) % MOD
    return total_good_sequences


