def minimum_day_to_order(n, m, k, offers):
    # Track how many of each microtransaction we still need to buy
    remaining = k[:]

    # Special offers for each type of microtransaction on each day
    offers_by_day = {}
    for day, type_id in offers:
        if day not in offers_by_day:
            offers_by_day[day] = []
        offers_by_day[day].append(type_id - 1)  # Zero-based index for types

    # Ivan starts with 0 burles
    burles = 0
    day = 0

    while sum(remaining) > 0:
        day += 1
        # If there are any offers on this day, use them
        if day in offers_by_day:
            for type_id in offers_by_day[day]:
                # Try to buy as many as possible of this type at the sale price
                if remaining[type_id] > 0:
                    can_buy_on_sale = min(remaining[type_id], burles)
                    remaining[type_id] -= can_buy_on_sale
                    burles -= can_buy_on_sale

        # Buy microtransactions at regular price for each type
        for i in range(n):
            if remaining[i] > 0:
                # How many to buy at regular price (2 burles each)
                buy_now = remaining[i]
                total_cost = 2 * buy_now
                if burles < total_cost:
                    # If we can't afford them, we need more burles
                    additional_days_needed = (total_cost - burles)
                    burles += additional_days_needed
                    day += additional_days_needed
        return day

