def max_product_array(a):
    n = len(a)

    # Count positives, negatives, and zeros
    pos_count = sum(1 for x in a if x > 0)
    neg_count = sum(1 for x in a if x < 0)
    zero_count = sum(1 for x in a if x == 0)

    result = []

    # Handle negatives
    neg_values = [x for x in a if x < 0]
    if neg_count % 2 == 0:
        # Even number of negatives, flip all to positive
        for x in a:
            if x < 0:
                result.append(-x - 1)
            else:
                result.append(-(x + 1))
    else:
        # Odd number of negatives, flip all but the smallest to positive
        neg_values.sort()
        smallest_neg = neg_values[0]
        for x in a:
            if x == smallest_neg:
                result.append(x)
            elif x < 0:
                result.append(-x - 1)
            else:
                result.append(-(x + 1))

    # Handle zeros
    if zero_count > 0 and pos_count == 0:
        # If there are zeros and no positives, keep one zero and flip others
        if neg_count > 0:
            if neg_count % 2 == 0:
                result = [-x - 1 for x in a if x != 0]
                result.append(0)
            else:
                result = [-x - 1 for x in a if x != smallest_neg]
                result.append(smallest_neg)
                result.append(0)
        else:
            return [0] * n

    return result


