def solve(n, Q, edges, conditions):
    # Build adjacency list for the tree
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Initialize the xor values for all nodes
    xor_values = [-1] * (n + 1)

    # Run DFS to assign xor values for the nodes
    dfs(1, -1, 0, adj, xor_values, conditions)

    # Create a union-find (disjoint-set) data structure
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if size[root_x] > size[root_y]:
                root_x, root_y = root_y, root_x
            parent[root_x] = root_y
            size[root_y] += size[root_x]

    # Apply conditions to union the nodes
    for u, v, x in conditions:
        if xor_values[u] == -1 or xor_values[v] == -1:
