        # Check if the condition is valid based on the xor values of u and v
        if (xor_values[u] ^ xor_values[v]) != x:
            return 0  # Impossible to satisfy the condition

    # Count the number of connected components
    components = 0
    for i in range(1, n + 1):
        if find(i) == i:
            components += 1

    # The number of ways to assign the weights is 2^components
    return pow(2, components, MOD)

