def does_intersect(p1, p2, q1, q2):
    """Check if line segments (p1, p2) and (q1, q2) intersect."""

    def orientation(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    o1 = orientation(p1, p2, q1)
    o2 = orientation(p1, p2, q2)
    o3 = orientation(q1, q2, p1)
    o4 = orientation(q1, q2, p2)

    if o1 != 0 and o2 != 0 and o3 != 0 and o4 != 0:
        # General case
        return (o1 != o2) and (o3 != o4)

    # Special cases where points are collinear
    if (
        o1 == 0
        and min(p1[0], p2[0]) <= q1[0] <= max(p1[0], p2[0])
        and min(p1[1], p2[1]) <= q1[1] <= max(p1[1], p2[1])
    ):
        return True
    if (
        o2 == 0
        and min(p1[0], p2[0]) <= q2[0] <= max(p1[0], p2[0])
        and min(p1[1], p2[1]) <= q2[1] <= max(p1[1], p2[1])
