def bpm(bp, u, matchR, seen):
    """Bipartite Matching utility function."""
    for v in range(len(matchR)):
        if bp[u][v] and not seen[v]:
            seen[v] = True

            if matchR[v] < 0 or bpm(bp, matchR[v], matchR, seen):
                matchR[v] = u
                return True
    return False


