    """Check if it is possible to assign rebel spaceships to bases without intersections."""
    bp = [[False] * B for _ in range(R)]

    # Create bipartite graph
    for i in range(R):
        for j in range(B):
            valid = True
            for k in range(R):
                for l in range(B):
