def find_min_k_for_idempotence(n, f_values):
    def is_idempotent(f):
        for x in range(1, n + 1):
            if f[x] != f[f[x]]:
                return False
        return True

    # Create a dictionary to map from 1-based index to the actual function value
    f = {i + 1: f_values[i] for i in range(n)}

    # Iterate over possible values of k starting from 1
    k = 1
    current_f = f.copy()

    while not is_idempotent(current_f):
        new_f = {}
        for x in range(1, n + 1):
            new_f[x] = current_f[current_f[x]]
        current_f = new_f
        k += 1

    return k


