def calculate_winning_probability(a1, b1, a2, b2):
    # Function to calculate all possible sums from two dice
    def get_sums(a, b):
        sums = {}
        for i in range(a, b + 1):
            for j in range(a, b + 1):
                total = i + j
                if total in sums:
                    sums[total] += 1
                else:
                    sums[total] = 1
        return sums

    # Get all possible sums for Gunnar and Emma
    gunnar_sums = get_sums(a1, b1)
    emma_sums = get_sums(a2, b2)

    # Calculate total number of outcomes for Gunnar and Emma
    total_gunnar_outcomes = (b1 - a1 + 1) ** 2
    total_emma_outcomes = (b2 - a2 + 1) ** 2

    # Initialize counters for wins
    gunnar_wins = 0
    emma_wins = 0

    # Compare all possible sums
    for gunnar_sum in gunnar_sums:
        for emma_sum in emma_sums:
            if gunnar_sum > emma_sum:
                gunnar_wins += gunnar_sums[gunnar_sum] * emma_sums[emma_sum]
            elif emma_sum > gunnar_sum:
                emma_wins += gunnar_sums[gunnar_sum] * emma_sums[emma_sum]

