def minPath(grid, k):
    from collections import deque

    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def bfs(start):
        queue = deque([(start, [grid[start[0]][start[1]]])])
        visited = set()
        visited.add(start)
        while queue:
            (x, y), path = queue.popleft()
            if len(path) == k:
                return path
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [grid[nx][ny]]))

    result = []
    for i in range(N):
        for j in range(N):
            path = bfs((i, j))
            if not result or path < result:
                result = path
    return result

