class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.parity = [0] * n  # This will store the parity of the path from the root

    def find(self, u):
        if self.parent[u] != u:
            orig_parent = self.parent[u]
            self.parent[u] = self.find(self.parent[u])
            self.parity[u] ^= self.parity[orig_parent]  # Adjust parity on path compression
        return self.parent[u]

    def union(self, u, v, parity):
        root_u = self.find(u)
        root_v = self.find(v)

        if root_u != root_v:
            # Union by rank
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
                self.parity[root_v] = self.parity[u] ^ self.parity[v] ^ parity
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
                self.parity[root_u] = self.parity[u] ^ self.parity[v] ^ parity
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1
                self.parity[root_v] = self.parity[u] ^ self.parity[v] ^ parity
        else:
            # They are already connected, check if the current parity matches the condition
            if (self.parity[u] ^ self.parity[v]) != parity:
                return False  # Conflict in conditions
        return True

def solve():
    t = int(input())  # Number of test cases
    for _ in range(t):
        n, q = map(int, input().split())  # n nodes, q conditions
        uf = UnionFind(n)

        # Read the tree edges (n-1 edges)
        for _ in range(n - 1):
            u, v = map(int, input().split())
            u -= 1  # convert to 0-indexed
            v -= 1  # convert to 0-indexed

        # Process the conditions
        for _ in range(q):
