        else:
            # If no contradiction found, calculate the number of ways to assign binary weights
            # The number of ways is 2^(number of independent components) since each component can
            # independently choose a binary assignment
            components = sum(1 for i in range(n) if uf.find(i) == i)
            print(pow(2, components - 1, MOD))

