from itertools import combinations_with_replacement


def find_partitions(n):
    """Generate all unique partitions of n."""
    partitions = set()

    def partition_recursive(start, current_partition):
        if sum(current_partition) == n:
            partitions.add(tuple(sorted(current_partition)))
        elif sum(current_partition) < n:
            for i in range(start, n + 1 - sum(current_partition)):
                partition_recursive(i, current_partition + [i])

    partition_recursive(1, [])
    return partitions


def find_part_max_prod(n):
    partitions = find_partitions(n)
    max_product = 0
    max_partitions = []

    for partition in partitions:
        product = 1
        for num in partition:
            product *= num
        if product > max_product:
            max_product = product
            max_partitions = [list(partition)]
        elif product == max_product:
            max_partitions.append(list(partition))

    # Sort the partitions by their length
    max_partitions.sort(key=len)

    # Return the result as specified
    return max_partitions + [max_product]


