def can_return_to_zero(n, rotations):
    # We'll use recursion or bit manipulation to explore all combinations of rotations
    def dfs(i, current_sum):
        # Base case: If we have processed all rotations
        if i == n:
            return current_sum % 360 == 0
        # Try both clockwise (+rotations[i]) and counterclockwise (-rotations[i])
        return dfs(i + 1, current_sum + rotations[i]) or dfs(i + 1, current_sum - rotations[i])

    # Start the recursive search with index 0 and sum 0
    return "YES" if dfs(0, 0) else "NO"

