def solve_star_grid(n, m, grid):
    # Directions for checking if we can place a star of size s at position (x, y)
    directions = [(0, 0), (0, -1), (0, 1), (-1, 0), (1, 0)]

    def is_valid(x, y, s):
        for dx, dy in directions:
            nx, ny = x + dx * s, y + dy * s
            if not (0 <= nx < n and 0 <= ny < m):
                return False
            if grid[nx][ny] == ".":
                return False
        return True

    used = [[False] * m for _ in range(n)]
    stars = []

    for i in range(1, n - 1):
        for j in range(1, m - 1):
            if grid[i][j] == "*":
                max_size = min(i, n - i - 1, j, m - j - 1)
                placed = False
                for s in range(max_size, 0, -1):
                    if is_valid(i, j, s):
                        stars.append((i + 1, j + 1, s))
                        for dx in range(-s, s + 1):
                            for dy in range(-s, s + 1):
                                if abs(dx) + abs(dy) > s:
                                    continue
                                used[i + dx][j + dy] = True
                        placed = True
                        break
                if not placed:
                    return -1

    # Check if all '*' positions are covered
    for i in range(n):
        for j in range(m):
            if grid[i][j] == "*" and not used[i][j]:
                return -1

    return len(stars), stars


