def distribute_news(n, m, groups):
    from collections import defaultdict, deque

    # Step 1: Build the graph
    graph = defaultdict(list)
    for group in groups:
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                u, v = group[i], group[j]
                graph[u].append(v)
                graph[v].append(u)

    # Step 2: Find connected components
    visited = [False] * (n + 1)
    component_sizes = [0] * (n + 1)

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        size = 0
        while queue:
            current = queue.popleft()
            size += 1
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return size

    # Compute sizes of all connected components
    for user in range(1, n + 1):
        if not visited[user]:
            component_size = bfs(user)
            for v in graph[user]:
                if not visited[
                    v
                ]:  # Only mark unvisited neighbors as part of the same component
                    component_sizes[v] = component_size
            component_sizes[user] = component_size

    # Step 3: Prepare the result for each user
    result = []
    for user in range(1, n + 1):
        result.append(component_sizes[user])

    return result

