import math


def max_coprime_divisors(A, B):
    # Step 1: Calculate the GCD of A and B
    gcd_value = math.gcd(A, B)

    # Step 2: Count the number of distinct prime factors of gcd_value
    def count_distinct_prime_factors(n):
        count = 0
        # Check for number of 2s that divide n
        if n % 2 == 0:
            count += 1
            while n % 2 == 0:
                n //= 2

        # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            # While i divides n, add i and divide n
            if n % i == 0:
                count += 1
                while n % i == 0:
                    n //= i

        # This condition is to check if n is a prime number greater than 2
        if n > 2:
            count += 1

        return count

    # Step 3: Get the count of distinct prime factors of gcd_value
    return count_distinct_prime_factors(gcd_value)


